public int[] largestPermBrute(int n, int[] arr, int k) {
    int[] best = arr.clone();
    search(arr.clone(), k, best);
    return best;
}

private void search(int[] cur, int k, int[] best) {
    if (compare(cur, best) > 0) System.arraycopy(cur, 0, best, 0, cur.length);
    if (k == 0) return;
    for (int i = 0; i < cur.length; i++) {
        for (int j = i + 1; j < cur.length; j++) {
            int t = cur[i]; cur[i] = cur[j]; cur[j] = t;
            search(cur, k - 1, best);
            t = cur[i]; cur[i] = cur[j]; cur[j] = t;
        }
    }
}

private int compare(int[] a, int[] b) {
    for (int i = 0; i < a.length; i++) if (a[i] != b[i]) return Integer.compare(a[i], b[i]);
    return 0;
}

