def largest_perm_brute(n: int, arr: list[int], k: int) -> list[int]:
    best = arr[:]

    def search(cur: list[int], k: int) -> None:
        nonlocal best
        if cur > best:
            best = cur[:]
        if k == 0:
            return
        for i in range(len(cur)):
            for j in range(i + 1, len(cur)):
                cur[i], cur[j] = cur[j], cur[i]
                search(cur, k - 1)
                cur[i], cur[j] = cur[j], cur[i]

    search(arr[:], k)
    return best

