public int[] largestPermutation(int n, int[] arr, long k) {
    Map<Integer, Integer> pos = new HashMap<>();
    for (int i = 0; i < n; i++) pos.put(arr[i], i);
    for (int i = 0; i < n && k > 0; i++) {
        int want = n - i;
        if (arr[i] != want) {
            int j = pos.get(want);
            int moved = arr[i];
            arr[i] = want;
            arr[j] = moved;
            pos.put(moved, j);
            pos.put(want, i);
            k--;
        }
    }
    return arr;
}

