def largest_permutation(n: int, arr: list[int], k: int) -> list[int]:
    pos = {v: i for i, v in enumerate(arr)}
    for i in range(n):
        if k == 0:
            break
        want = n - i
        if arr[i] != want:
            j = pos[want]
            moved = arr[i]
            arr[i], arr[j] = want, moved
            pos[moved] = j
            pos[want] = i
            k -= 1
    return arr

